import numpy as np

def problem(x: np.ndarray) -> float:
    """
    A synthetic benchmark function combining a skewed quadratic bowl,
    sinusoidal modulation along dimensions, and a few additional terms for fine-tuning ELA features.

    Formula:
    f(x) = quadratic_bowl(x) + sinusoidal_modulation(x) + skew_term(x) + interaction_term(x)

    Where:
    - quadratic_bowl(x) = sum(i * x[i]^2)
    - sinusoidal_modulation(x) = sum(sin(2*x[i]))
    - skew_term(x) = sum(x[i]^3) * 0.005
    - interaction_term(x) = 0.002 * (x[0] * x[1] - x[1]*x[2])
    """
    def quadratic_bowl(x):
        return np.sum(np.arange(1, len(x) + 1) * (x * x))

    def sinusoidal_modulation(x):
        return np.sum(np.sin(2 * x))

    def skew_term(x):
        return np.sum(x**3) * 0.005

    def interaction_term(x):
        return 0.002 * (x[0] * x[1] - x[1] * x[2])

    return quadratic_bowl(x) + sinusoidal_modulation(x) + skew_term(x) + interaction_term(x)
